import re

LABEL = re.compile(r'[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\Z')


def ident(value):
    if not isinstance(value, str) or not LABEL.fullmatch(value):
        raise ValueError('DNS label required')
    return value


def labels(value):
    if not isinstance(value, dict) or not value or any(not isinstance(k, str) or not k or not isinstance(v, str) for k, v in value.items()):
        raise ValueError('nonempty exact label map required')
    return value


def host(value, namespace):
    if not isinstance(value, str):
        raise ValueError('host')
    if '.' not in value:
        return ident(value) + '.' + namespace + '.svc.cluster.local'
    parts = value.split('.')
    if len(parts) != 5 or parts[2:] != ['svc', 'cluster', 'local']:
        raise ValueError('only short host or full Kubernetes service FQDN supported')
    ident(parts[0]); ident(parts[1])
    return value


def rows(data, key, fields):
    value = data[key]
    if not isinstance(value, list):
        raise ValueError('list required')
    for row in value:
        if not isinstance(row, dict) or set(row) != fields:
            raise ValueError('schema')
    return value


def audit(data):
    if not isinstance(data, dict) or set(data) != {'services', 'pods', 'destination_rules', 'routes'}:
        raise ValueError('top-level schema')
    services = {}
    for service in rows(data, 'services', {'name', 'namespace', 'selector'}):
        ident(service['name']); ident(service['namespace']); labels(service['selector'])
        key = host(service['name'], service['namespace'])
        if key in services:
            raise ValueError('duplicate service')
        services[key] = service
    pods = []
    seen = set()
    for pod in rows(data, 'pods', {'name', 'namespace', 'labels', 'ready'}):
        ident(pod['name']); ident(pod['namespace']); labels(pod['labels'])
        if type(pod['ready']) is not bool:
            raise ValueError('ready must be bool')
        key = pod['namespace'] + '/' + pod['name']
        if key in seen:
            raise ValueError('duplicate pod')
        seen.add(key); pods.append(pod)
    rules = {}; seen = set()
    for rule in rows(data, 'destination_rules', {'name', 'namespace', 'host', 'subsets'}):
        ident(rule['name']); ident(rule['namespace'])
        key = rule['namespace'] + '/' + rule['name']
        if key in seen or not isinstance(rule['subsets'], list):
            raise ValueError('duplicate or invalid rule')
        seen.add(key)
        names = set()
        for subset in rule['subsets']:
            if not isinstance(subset, dict) or set(subset) != {'name', 'labels'}:
                raise ValueError('subset schema')
            ident(subset['name']); labels(subset['labels'])
            if subset['name'] in names:
                raise ValueError('duplicate subset')
            names.add(subset['name'])
        rules.setdefault(host(rule['host'], rule['namespace']), []).append(rule)
    routes = []; seen = set()
    for route in rows(data, 'routes', {'id', 'namespace', 'host', 'subset'}):
        ident(route['id']); ident(route['namespace'])
        if route['subset'] is not None:
            ident(route['subset'])
        if route['id'] in seen:
            raise ValueError('duplicate route')
        seen.add(route['id'])
        fqdn = host(route['host'], route['namespace'])
        service = services.get(fqdn)
        problem = None; selected = {}; matched = []; ready = []
        if service is None:
            problem = 'service_missing'
        else:
            selected = dict(service['selector'])
            if route['subset'] is not None:
                candidates = rules.get(fqdn, [])
                if not candidates:
                    problem = 'destination_rule_missing'
                elif len(candidates) != 1:
                    problem = 'destination_rule_ambiguous'
                else:
                    subset = next((s for s in candidates[0]['subsets'] if s['name'] == route['subset']), None)
                    if subset is None:
                        problem = 'subset_missing'
                    elif any(k in selected and selected[k] != v for k, v in subset['labels'].items()):
                        problem = 'selector_conflict'
                    else:
                        selected.update(subset['labels'])
            if problem is None:
                for pod in pods:
                    if pod['namespace'] == service['namespace'] and all(pod['labels'].get(k) == v for k, v in selected.items()):
                        key = pod['namespace'] + '/' + pod['name']
                        matched.append(key)
                        if pod['ready']:
                            ready.append(key)
                if not ready:
                    problem = 'ready_pods_empty'
        routes.append({'id': route['id'], 'host': fqdn, 'problem': problem,
                       'matching_pods': sorted(matched), 'ready_pods': sorted(ready)})
    return {'routes': sorted(routes, key=lambda r: r['id']),
            'scope': 'static supplied inventory; not endpoint or mesh readiness proof'}

