def token(value):
    if not isinstance(value, str) or not value:
        raise ValueError('nonempty string required')
    return value


def port(value):
    if type(value) is not int or not 1 <= value <= 65535:
        raise ValueError('integer port required')
    return value


def evaluate(data):
    if not isinstance(data, dict) or set(data) != {'policies', 'requests'}:
        raise ValueError('schema')
    policies, requests = data['policies'], data['requests']
    if not isinstance(policies, list) or not isinstance(requests, list):
        raise ValueError('lists required')
    names = set()
    for policy in policies:
        if not isinstance(policy, dict) or set(policy) != {'name', 'action', 'rules'}:
            raise ValueError('policy schema')
        token(policy['name'])
        if policy['name'] in names or policy['action'] not in ('ALLOW', 'DENY') or not isinstance(policy['rules'], list):
            raise ValueError('policy fields')
        names.add(policy['name'])
        for rule in policy['rules']:
            if not isinstance(rule, dict) or set(rule) - {'ports', 'methods', 'paths'}:
                raise ValueError('rule schema')
            for key, values in rule.items():
                if not isinstance(values, list) or not values:
                    raise ValueError('nonempty exact-match list required')
                for value in values:
                    if key == 'ports':
                        port(value)
                    else:
                        token(value)
                        if '*' in value or (key == 'paths' and not value.startswith('/')):
                            raise ValueError('only exact HTTP attributes supported')
    seen = set()
    for request in requests:
        if not isinstance(request, dict):
            raise ValueError('request schema')
        protocol = request.get('protocol')
        fields = {'id', 'protocol', 'port'} | ({'method', 'path'} if protocol == 'HTTP' else set())
        if protocol not in ('HTTP', 'TCP') or set(request) != fields:
            raise ValueError('request protocol schema')
        token(request['id']); port(request['port'])
        if request['id'] in seen:
            raise ValueError('duplicate request')
        seen.add(request['id'])
        if protocol == 'HTTP':
            token(request['method']); token(request['path'])
            if not request['path'].startswith('/') or '*' in request['path'] or '*' in request['method']:
                raise ValueError('exact HTTP request required')

    def matches(policy, request):
        for rule in policy['rules']:
            match = True
            for key, values in rule.items():
                if key == 'ports':
                    match = match and request['port'] in values
                elif request['protocol'] == 'TCP':
                    match = match and policy['action'] == 'DENY'
                else:
                    match = match and request['method' if key == 'methods' else 'path'] in values
            if match:
                return True
        return False

    decisions = []
    has_allow = any(policy['action'] == 'ALLOW' for policy in policies)
    for request in requests:
        deny = sorted(p['name'] for p in policies if p['action'] == 'DENY' and matches(p, request))
        allow = sorted(p['name'] for p in policies if p['action'] == 'ALLOW' and matches(p, request))
        decisions.append({'id': request['id'], 'allowed': not deny and (not has_allow or bool(allow)),
                          'deny_matches': deny, 'allow_matches': allow})
    return {'decisions': sorted(decisions, key=lambda r: r['id']),
            'scope': 'normalized bound ALLOW/DENY subset; not actual Istio enforcement'}

