import heapq
import re


def integer(value, minimum, maximum):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError('bounded integer required')
    return value


def name(value):
    if not isinstance(value, str) or not re.fullmatch(r'[a-z][a-z0-9-]{0,62}', value):
        raise ValueError('name required')
    return value


def analyze(data):
    if not isinstance(data, dict) or set(data) != {'root', 'root_requests', 'nodes', 'edges'}:
        raise ValueError('schema')
    root = name(data['root']); initial = integer(data['root_requests'], 1, 10**9)
    if not isinstance(data['nodes'], list) or not 1 <= len(data['nodes']) <= 100:
        raise ValueError('nodes')
    if not isinstance(data['edges'], list) or len(data['edges']) > 1000:
        raise ValueError('edges')
    limits = {}
    for node in data['nodes']:
        if not isinstance(node, dict) or set(node) != {'name', 'max_requests'}:
            raise ValueError('node schema')
        key = name(node['name'])
        if key in limits:
            raise ValueError('duplicate node')
        limits[key] = integer(node['max_requests'], 0, 10**18)
    if root not in limits:
        raise ValueError('unknown root')
    adjacency = {key: [] for key in limits}; indegree = {key: 0 for key in limits}; ids = set()
    for edge in data['edges']:
        if not isinstance(edge, dict) or set(edge) != {'id', 'source', 'target', 'attempts', 'calls_per_request', 'per_try_ms', 'route_timeout_ms', 'replay_safe'}:
            raise ValueError('edge schema')
        ident = name(edge['id']); source = name(edge['source']); target = name(edge['target'])
        if ident in ids or source not in limits or target not in limits or type(edge['replay_safe']) is not bool:
            raise ValueError('edge fields')
        ids.add(ident)
        integer(edge['attempts'], 0, 16); integer(edge['calls_per_request'], 1, 10**6)
        integer(edge['per_try_ms'], 1, 10**12); integer(edge['route_timeout_ms'], 1, 10**12)
        adjacency[source].append(edge); indegree[target] += 1
    if indegree[root]:
        raise ValueError('root must have no incoming edge')
    pending = [key for key, count in indegree.items() if count == 0]; heapq.heapify(pending)
    order = []
    while pending:
        source = heapq.heappop(pending); order.append(source)
        for edge in adjacency[source]:
            indegree[edge['target']] -= 1
            if indegree[edge['target']] == 0:
                heapq.heappush(pending, edge['target'])
    if len(order) != len(limits):
        raise ValueError('cycles are unsupported')
    counts = {key: 0 for key in limits}; counts[root] = initial
    for source in order:
        for edge in adjacency[source]:
            counts[edge['target']] += counts[source] * edge['calls_per_request'] * (edge['attempts'] + 1)
    edge_reports = []
    for edge in sorted(data['edges'], key=lambda row: row['id']):
        attempts = edge['attempts'] + 1
        reservation = attempts * edge['per_try_ms']
        edge_reports.append({'id': edge['id'], 'max_attempts_per_call': attempts,
                             'full_per_try_reservation_ms': reservation,
                             'reservation_fits_without_backoff': reservation <= edge['route_timeout_ms'],
                             'unsafe_retry': edge['attempts'] > 0 and not edge['replay_safe']})
    return {'node_upper_bounds': [{'name': key, 'requests': counts[key], 'exceeds_budget': counts[key] > limits[key]} for key in sorted(limits)],
            'edges': edge_reports,
            'scope': 'configured DAG upper bounds; no actual retry count or latency guarantee'}

